mapper.select:
select *
from adi_file
where id > #{lastId}
  and ref_count = 0
  and is_deleted = false
  and create_time < #{ttl}
order by id asc
limit #{batchSize}

select *
from adi_file
where id > #{lastId}
  and is_deleted = true
  and update_time < #{before}
order by id asc
limit #{batchSize}

mapper.update:
update adi_file
set ref_count = #{refCount}
where id = #{id} and is_deleted = false

update adi_file
set is_deleted = false, ref_count = #{refCount}
where id = #{id} and is_deleted = true
